from alembic.config import Config
from alembic.script import ScriptDirectory
from httpx import AsyncClient


async def test_status_routes_answer_get_and_head(anon_client: AsyncClient) -> None:
    for path in ("/", "/health"):
        assert (await anon_client.get(path)).json()["status"] == "ok"
        # UptimeRobot's free monitors send HEAD
        assert (await anon_client.head(path)).status_code == 200


def test_single_alembic_head() -> None:
    # Two heads (e.g. a second autogenerated migration from the same parent) stop
    # `alembic upgrade head`, so Render's start command fails and the deploy never goes live.
    heads = ScriptDirectory.from_config(Config("alembic.ini")).get_heads()
    assert len(heads) == 1, f"Several Alembic heads: {heads}"
